from solution import get_max_triples
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _a(n):
    return [i * i - i + 1 for i in range(1, n + 1)]


def _reference(n):
    a = _a(n)
    c = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    c += 1
    return c


def _comb3(m):
    if m < 3:
        return 0
    return m * (m - 1) * (m - 2) // 6


# --- explicit spec example ---

def test_example_n5_equals_1():
    assert get_max_triples(5) == 1


def test_example_array_only_valid_triple():
    # a = [1, 3, 7, 13, 21]; spec says only (1,7,13) valid
    a = _a(5)
    assert a == [1, 3, 7, 13, 21]
    assert (a[0] + a[2] + a[3]) % 3 == 0
    assert _reference(5) == 1
    assert get_max_triples(5) == _reference(5)


# --- small-n boundary: must be integer 0, not False ---

@pytest.mark.parametrize("n", [1, 2])
def test_small_n_returns_int_zero(n):
    r = get_max_triples(n)
    assert r == 0
    assert type(r) is int


@pytest.mark.parametrize("n,expected", [
    (1, 0),
    (2, 0),
    (3, 0),
    (4, 1),
    (5, 1),
    (6, 4),
    (7, 10),
    (8, 11),
])
def test_known_values(n, expected):
    assert _reference(n) == expected
    r = get_max_triples(n)
    assert r == expected
    assert type(r) is int


# --- property: equivalence to brute-force reference ---

@given(st.integers(min_value=1, max_value=30))
def test_property_matches_brute_force(n):
    assert get_max_triples(n) == _reference(n)


@given(st.integers(min_value=1, max_value=100))
def test_property_matches_residue_count_formula(n):
    a = _a(n)
    # spec-derived invariant: residues are only 0 or 1
    for v in a:
        assert v % 3 in (0, 1)
    cnt0 = sum(1 for v in a if v % 3 == 0)
    cnt1 = n - cnt0
    # only all-equal triples can sum to 0 mod 3
    assert cnt0 == sum(1 for i in range(1, n + 1) if i % 3 == 2)
    expected = _comb3(cnt0) + _comb3(cnt1)
    assert expected == _reference(n)
    assert get_max_triples(n) == expected


# --- property: type and range ---

@given(st.integers(min_value=1, max_value=200))
def test_property_result_is_nonnegative_int(n):
    r = get_max_triples(n)
    assert type(r) is int
    assert r >= 0


@given(st.integers(min_value=1, max_value=200))
def test_property_result_bounded_by_all_triples(n):
    r = get_max_triples(n)
    assert r <= _comb3(n)


# --- property: monotonicity (adding an element cannot remove triples) ---

@given(st.integers(min_value=1, max_value=100))
def test_property_monotone_nondecreasing(n):
    assert get_max_triples(n + 1) >= get_max_triples(n)


# --- property: increment equals number of new valid pairs ---

@given(st.integers(min_value=1, max_value=50))
def test_property_increment_equals_new_pairs(n):
    # triples ending at n+1 that are valid
    a = _a(n + 1)
    last = a[-1]
    new = 0
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] + a[j] + last) % 3 == 0:
                new += 1
    assert get_max_triples(n + 1) - get_max_triples(n) == new
    assert new >= 0
